CREATE OR REPLACE FUNCTION public.set_staff_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_list_staff(p_search text DEFAULT NULL::text, p_role text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_shop_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  bid uuid := public.admin_require_caller_business_id();
  lim int := greatest(1, least(coalesce(p_limit, 50), 100));
  off int := greatest(0, least(coalesce(p_offset, 0), 100000));
  status_key text := nullif(lower(trim(coalesce(p_status, ''))), '');
  role_key text := nullif(lower(trim(coalesce(p_role, ''))), '');
  search_key text := nullif(trim(coalesce(p_search, '')), '');
  result jsonb;
begin
  if status_key is not null
     and status_key not in ('active', 'disabled', 'terminated', 'all') then
    raise exception 'invalid status filter' using errcode = '22023';
  end if;

  if role_key is not null
     and role_key not in ('owner', 'admin', 'manager', 'cashier', 'operator') then
    raise exception 'invalid role filter' using errcode = '22023';
  end if;

  select coalesce(jsonb_agg(row_to_json(x)::jsonb), '[]'::jsonb)
  into result
  from (
    select
      s.id as staff_id,
      s.username,
      s.display_name,
      s.role,
      s.active,
      s.terminated_at,
      s.created_at,
      s.updated_at,
      public.admin_staff_shops_json(s.id) as shops
    from public.staff s
    where s.business_id = bid
      and (role_key is null or s.role = role_key)
      and (
        status_key is null or status_key = 'all'
        or (status_key = 'active' and s.active and s.terminated_at is null)
        or (status_key = 'disabled' and not s.active and s.terminated_at is null)
        or (status_key = 'terminated' and s.terminated_at is not null)
      )
      and (
        search_key is null
        or position(lower(search_key) in lower(s.username)) > 0
        or position(lower(search_key) in lower(s.display_name)) > 0
      )
      and (
        p_shop_id is null
        or (
          s.role = 'owner'
          and exists (
            select 1 from public.shops sh
            where sh.id = p_shop_id
              and sh.business_id = bid
          )
        )
        or exists (
          select 1 from public.staff_shops ss
          where ss.staff_id = s.id and ss.shop_id = p_shop_id
        )
      )
    order by s.username asc
    limit lim
    offset off
  ) x;

  return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_list_activity(p_action text DEFAULT NULL::text, p_target_username text DEFAULT NULL::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  bid uuid := public.admin_require_caller_business_id();
  lim int := greatest(1, least(coalesce(p_limit, 50), 100));
  off int := greatest(0, least(coalesce(p_offset, 0), 100000));
  action_key text := nullif(trim(coalesce(p_action, '')), '');
  user_key text := nullif(lower(trim(coalesce(p_target_username, ''))), '');
  result jsonb;
begin
  select coalesce(jsonb_agg(row_to_json(x)::jsonb), '[]'::jsonb)
  into result
  from (
    select
      a.id,
      a.at,
      a.action,
      a.target_username,
      a.detail
    from public.audit_log a
    where a.business_id = bid
      and (action_key is null or a.action = action_key)
      and (
        user_key is null
        or a.target_username = user_key
        or (
          a.target_username is not null
          and position(user_key in a.target_username) > 0
        )
      )
      and (p_from is null or a.at >= p_from)
      and (p_to is null or a.at <= p_to)
    order by a.at desc, a.id desc
    limit lim
    offset off
  ) x;

  return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_create_staff_db(p_auth_user_id uuid, p_username text, p_display_name text, p_role text, p_shop_ids uuid[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  caller record;
  v_username text;
  v_staff_id uuid;
  v_shop_id uuid;
BEGIN
  caller := public.admin_require_write_caller();

  v_username := lower(btrim(p_username));
  IF v_username = '' THEN
    RAISE EXCEPTION 'Username is required' USING errcode = 'P0008';
  END IF;

  IF p_role NOT IN ('owner', 'admin', 'manager', 'cashier', 'operator') THEN
    RAISE EXCEPTION 'Invalid role' USING errcode = '22023';
  END IF;

  IF p_role IN ('owner', 'admin') AND caller.caller_role != 'owner' THEN
    RAISE EXCEPTION 'Only owners can create owners or admins' USING errcode = '42501';
  END IF;

  IF p_role != 'owner' AND (p_shop_ids IS NULL OR array_length(p_shop_ids, 1) IS NULL) THEN
    RAISE EXCEPTION 'Non-owners require at least one shop assignment' USING errcode = 'P0009';
  END IF;

  PERFORM id FROM public.businesses WHERE id = caller.business_id FOR UPDATE;

  INSERT INTO public.staff (
    business_id,
    auth_user_id,
    username,
    display_name,
    role,
    active
  ) VALUES (
    caller.business_id,
    p_auth_user_id,
    v_username,
    btrim(p_display_name),
    p_role,
    true
  ) RETURNING id INTO v_staff_id;

  IF p_shop_ids IS NOT NULL THEN
    FOREACH v_shop_id IN ARRAY p_shop_ids LOOP
      IF NOT EXISTS (SELECT 1 FROM public.shops WHERE id = v_shop_id AND business_id = caller.business_id) THEN
        RAISE EXCEPTION 'Shop not found' USING errcode = 'P0005';
      END IF;

      INSERT INTO public.staff_shops (staff_id, shop_id)
      VALUES (v_staff_id, v_shop_id)
      ON CONFLICT DO NOTHING;
    END LOOP;
  END IF;

  PERFORM public.admin_write_audit(
    caller.business_id,
    'create',
    v_username,
    jsonb_build_object('staff_id', v_staff_id, 'role', p_role, 'shops', p_shop_ids),
    caller.staff_id,
    caller.username
  );

  RETURN v_staff_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.redact_json_secrets(p_val jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  k text;
  v jsonb;
  res jsonb;
BEGIN
  IF jsonb_typeof(p_val) = 'object' THEN
    res := '{}'::jsonb;
    FOR k, v IN SELECT * FROM jsonb_each(p_val) LOOP
      IF lower(k) IN (
        'password', 'password_hash', 'credential', 'server_credential',
        'secret', 'token', 'apikey', 'api_key', 'refresh_token',
        'access_token', 'authorization', 'cookie', 'set-cookie',
        'verifier', 'recovery_code'
      ) THEN
        res := jsonb_set(res, ARRAY[k], '"[REDACTED]"'::jsonb);
      ELSE
        res := jsonb_set(res, ARRAY[k], public.redact_json_secrets(v));
      END IF;
    END LOOP;
    RETURN res;
  ELSIF jsonb_typeof(p_val) = 'array' THEN
    res := '[]'::jsonb;
    FOR v IN SELECT * FROM jsonb_array_elements(p_val) LOOP
      res := res || public.redact_json_secrets(v);
    END LOOP;
    RETURN res;
  ELSE
    RETURN p_val;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_disable_staff(p_staff_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  caller record;
  target record;
BEGIN
  caller := public.admin_require_write_caller();

  -- 1. Lock Business
  PERFORM id FROM public.businesses WHERE id = caller.business_id FOR UPDATE;

  -- 2. Get target staff FOR UPDATE to lock it
  SELECT * INTO target
  FROM public.staff
  WHERE id = p_staff_id AND business_id = caller.business_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Staff not found' USING errcode = '42P01';
  END IF;

  IF target.terminated_at IS NOT NULL THEN
    RAISE EXCEPTION 'Cannot disable a terminated account' USING errcode = 'P0003';
  END IF;

  IF target.active = false THEN
    RETURN; -- Idempotent
  END IF;

  IF target.role = 'owner' THEN
    PERFORM public.admin_ensure_not_last_active_owner(caller.business_id, target.id);
  END IF;

  UPDATE public.staff
  SET active = false
  WHERE id = p_staff_id;

  PERFORM public.admin_write_audit(
    caller.business_id,
    'disable',
    target.username,
    jsonb_build_object('staff_id', target.id),
    caller.staff_id,
    caller.username
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_enable_staff(p_staff_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  caller record;
  target record;
BEGIN
  caller := public.admin_require_write_caller();

  PERFORM id FROM public.businesses WHERE id = caller.business_id FOR UPDATE;

  SELECT * INTO target
  FROM public.staff
  WHERE id = p_staff_id AND business_id = caller.business_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Staff not found' USING errcode = '42P01';
  END IF;

  IF target.terminated_at IS NOT NULL THEN
    RAISE EXCEPTION 'Cannot enable a terminated account' USING errcode = 'P0003';
  END IF;

  IF target.active = true THEN
    RETURN;
  END IF;

  UPDATE public.staff
  SET active = true
  WHERE id = p_staff_id;

  PERFORM public.admin_write_audit(
    caller.business_id,
    'enable',
    target.username,
    jsonb_build_object('staff_id', target.id),
    caller.staff_id,
    caller.username
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_assign_shop(p_staff_id uuid, p_shop_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  caller record;
  target record;
  shop_record record;
BEGIN
  caller := public.admin_require_write_caller();

  -- Verify staff
  SELECT * INTO target
  FROM public.staff
  WHERE id = p_staff_id AND business_id = caller.business_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Staff not found' USING errcode = '42P01';
  END IF;

  IF target.terminated_at IS NOT NULL THEN
    RAISE EXCEPTION 'Cannot assign shops to a terminated account' USING errcode = 'P0003';
  END IF;

  -- Verify shop
  SELECT * INTO shop_record
  FROM public.shops
  WHERE id = p_shop_id AND business_id = caller.business_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Shop not found' USING errcode = 'P0005';
  END IF;

  -- Insert idempotently
  INSERT INTO public.staff_shops (staff_id, shop_id)
  VALUES (p_staff_id, p_shop_id)
  ON CONFLICT DO NOTHING;

  IF FOUND THEN
    PERFORM public.admin_write_audit(
      caller.business_id,
      'assign_shop',
      target.username,
      jsonb_build_object('staff_id', target.id, 'shop_id', shop_record.id, 'shop', shop_record.name),
      caller.staff_id,
      caller.username
    );
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_unassign_shop(p_staff_id uuid, p_shop_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  caller record;
  target record;
  shop_record record;
BEGIN
  caller := public.admin_require_write_caller();

  SELECT * INTO target
  FROM public.staff
  WHERE id = p_staff_id AND business_id = caller.business_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Staff not found' USING errcode = '42P01';
  END IF;

  SELECT * INTO shop_record
  FROM public.shops
  WHERE id = p_shop_id AND business_id = caller.business_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Shop not found' USING errcode = 'P0005';
  END IF;

  DELETE FROM public.staff_shops
  WHERE staff_id = p_staff_id AND shop_id = p_shop_id;

  IF FOUND THEN
    PERFORM public.admin_write_audit(
      caller.business_id,
      'unassign_shop',
      target.username,
      jsonb_build_object('staff_id', target.id, 'shop_id', shop_record.id, 'shop', shop_record.name),
      caller.staff_id,
      caller.username
    );
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_add_shop(p_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  caller record;
  v_name text;
  v_shop_id uuid;
BEGIN
  caller := public.admin_require_write_caller();

  v_name := btrim(p_name);
  IF v_name = '' THEN
    RAISE EXCEPTION 'Shop name is required' USING errcode = 'P0006';
  END IF;

  -- Ensure uniqueness
  IF EXISTS (
    SELECT 1 FROM public.shops
    WHERE business_id = caller.business_id AND name = v_name
  ) THEN
    RAISE EXCEPTION 'Shop already exists' USING errcode = 'P0007';
  END IF;

  INSERT INTO public.shops (business_id, name, active)
  VALUES (caller.business_id, v_name, true)
  RETURNING id INTO v_shop_id;

  PERFORM public.admin_write_audit(
    caller.business_id,
    'add_shop',
    NULL,
    jsonb_build_object('shop_id', v_shop_id, 'name', v_name),
    caller.staff_id,
    caller.username
  );

  RETURN jsonb_build_object('id', v_shop_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_terminate_staff_db(p_staff_id uuid, p_confirm_username text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  caller record;
  target record;
  v_old_auth_user_id uuid;
  v_now timestamptz;
BEGIN
  caller := public.admin_require_write_caller();

  IF caller.caller_role != 'owner' THEN
    RAISE EXCEPTION 'Only owners can terminate accounts' USING errcode = '42501';
  END IF;

  -- 1. Lock Business
  PERFORM id FROM public.businesses WHERE id = caller.business_id FOR UPDATE;

  -- 2. Lock target row
  SELECT * INTO target
  FROM public.staff
  WHERE id = p_staff_id AND business_id = caller.business_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Staff not found' USING errcode = '42P01';
  END IF;

  IF target.terminated_at IS NOT NULL THEN
    RETURN target.auth_user_id; -- Idempotent
  END IF;

  IF target.username != lower(btrim(p_confirm_username)) THEN
    RAISE EXCEPTION 'Confirmation username does not match' USING errcode = 'P0010';
  END IF;

  IF target.role = 'owner' AND target.active = true THEN
    PERFORM public.admin_ensure_not_last_active_owner(caller.business_id, target.id);
  END IF;

  v_old_auth_user_id := target.auth_user_id;
  v_now := now();

  UPDATE public.staff
  SET active = false,
      terminated_at = v_now,
      auth_user_id = NULL
  WHERE id = p_staff_id;

  PERFORM public.admin_write_audit(
    caller.business_id,
    'terminate',
    target.username,
    jsonb_build_object('staff_id', target.id, 'terminated_at', v_now),
    caller.staff_id,
    caller.username
  );

  RETURN v_old_auth_user_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_record_auth_reconciliation(p_business_id uuid, p_operation text, p_auth_user_id uuid, p_target_username text, p_performed_by uuid, p_performed_by_username text, p_error_code text, p_correlation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_id uuid;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'service role required' USING errcode = '42501';
  END IF;
  IF p_operation NOT IN ('create_cleanup', 'terminate_cleanup', 'reset_audit') THEN
    RAISE EXCEPTION 'invalid reconciliation operation' USING errcode = 'P0011';
  END IF;
  IF p_error_code NOT IN (
    'ALREADY_EXISTS', 'FORBIDDEN', 'INVALID_INPUT', 'NOT_FOUND',
    'RATE_LIMITED', 'SERVER_ERROR', 'UNREACHABLE', 'UNKNOWN'
  ) THEN
    RAISE EXCEPTION 'invalid reconciliation error code' USING errcode = 'P0012';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.staff
    WHERE id = p_performed_by
      AND business_id = p_business_id
      AND username = p_performed_by_username
  ) THEN
    RAISE EXCEPTION 'invalid reconciliation performer' USING errcode = '42501';
  END IF;

  INSERT INTO public.auth_reconciliation (
    business_id, operation, auth_user_id, target_username, state,
    attempt_count, error_code, correlation_id, performed_by,
    performed_by_username, created_at, updated_at
  ) VALUES (
    p_business_id, p_operation, p_auth_user_id, lower(btrim(p_target_username)),
    'pending', 1, p_error_code, p_correlation_id, p_performed_by,
    p_performed_by_username, now(), now()
  )
  ON CONFLICT (operation, auth_user_id) WHERE state = 'pending'
  DO UPDATE SET
    attempt_count = public.auth_reconciliation.attempt_count + 1,
    error_code = EXCLUDED.error_code,
    correlation_id = EXCLUDED.correlation_id,
    updated_at = now(),
    last_attempt_at = now()
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_set_role(p_staff_id uuid, p_new_role text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  caller record;
  target record;
BEGIN
  caller := public.admin_require_write_caller();

  IF p_new_role IN ('owner', 'admin') AND caller.caller_role != 'owner' THEN
    RAISE EXCEPTION 'Only owners can promote to owner or admin' USING errcode = '42501';
  END IF;

  IF p_new_role NOT IN ('owner', 'admin', 'manager', 'cashier', 'operator') THEN
    RAISE EXCEPTION 'Invalid role' USING errcode = '22023';
  END IF;

  -- 1. Lock Business
  PERFORM id FROM public.businesses WHERE id = caller.business_id FOR UPDATE;

  -- 2. Lock Target
  SELECT * INTO target
  FROM public.staff
  WHERE id = p_staff_id AND business_id = caller.business_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Staff not found' USING errcode = '42P01';
  END IF;

  IF target.terminated_at IS NOT NULL THEN
    RAISE EXCEPTION 'Cannot change role on a terminated account' USING errcode = 'P0003';
  END IF;

  IF target.role = p_new_role THEN
    RETURN;
  END IF;

  IF target.role = 'owner' THEN
    IF caller.caller_role != 'owner' THEN
      RAISE EXCEPTION 'Only owners can demote an owner' USING errcode = '42501';
    END IF;
    IF target.active = true THEN
      PERFORM public.admin_ensure_not_last_active_owner(caller.business_id, target.id);
    END IF;
  END IF;

  UPDATE public.staff
  SET role = p_new_role
  WHERE id = p_staff_id;

  PERFORM public.admin_write_audit(
    caller.business_id,
    'set_role',
    target.username,
    jsonb_build_object('staff_id', target.id, 'old_role', target.role, 'new_role', p_new_role),
    caller.staff_id,
    caller.username
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_record_reset_credential_audit(p_staff_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  caller record;
  target record;
BEGIN
  caller := public.admin_require_write_caller();
  SELECT id, username, terminated_at INTO target
  FROM public.staff
  WHERE id = p_staff_id AND business_id = caller.business_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'staff not found' USING errcode = '42P01';
  END IF;
  IF target.terminated_at IS NOT NULL THEN
    RAISE EXCEPTION 'terminated account' USING errcode = 'P0003';
  END IF;
  PERFORM public.admin_write_audit(
    caller.business_id,
    'reset_server_credential',
    target.username,
    jsonb_build_object('staff_id', target.id),
    caller.staff_id,
    caller.username
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_records_assign_seq()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'INSERT' then
    new.server_seq := nextval('public.sync_records_server_seq_seq');
    return new;
  end if;
  if public.sync_normalize_payload(new.payload)
     is not distinct from public.sync_normalize_payload(old.payload) then
    return new;  -- unchanged: leave explicitly-set values alone
  end if;
  new.server_seq := nextval('public.sync_records_server_seq_seq');
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.sync_push(envelopes jsonb, device_id text DEFAULT NULL::text, shop_id uuid DEFAULT NULL::uuid, pull_cursor bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_staff       record;
  v_shop        uuid;
  v_env         jsonb;
  v_table       text;
  v_uid         text;
  v_payload     jsonb;
  v_parked_seq  bigint;
  v_existing    public.sync_records%rowtype;
  v_applied     int := 0;
  v_conflicts   int := 0;
begin
  select s.id, s.business_id, s.role, s.username into v_staff
    from public.staff s
   where s.auth_user_id = auth.uid() and s.active and s.terminated_at is null;
  if not found then
    return jsonb_build_object('ok', false, 'error', jsonb_build_object(
      'code', 'not_authorized', 'message', 'No active staff profile'));
  end if;

  -- erratum 1: nullif(shop_id,'') casts '' to the uuid param at plan time (22P02)
  v_shop := shop_id;
  if v_shop is null or v_shop not in (select public.sync_staff_shop_ids()) then
    return jsonb_build_object('ok', false, 'error', jsonb_build_object(
      'code', 'shop_required', 'message',
      'The request must name a shop this account may write to'));
  end if;

  if jsonb_typeof(envelopes) <> 'array' or jsonb_array_length(envelopes) > 500 then
    return jsonb_build_object('ok', false, 'error', jsonb_build_object(
      'code', 'too_many_envelopes', 'message',
      'Send between 0 and 500 envelopes per call'));
  end if;

  -- INVARIANT 1: seq order == commit order per shop
  perform pg_advisory_xact_lock(hashtextextended(v_shop::text, 0));

  for v_env in select * from jsonb_array_elements(envelopes) loop
    v_table      := v_env->>'table';
    v_uid        := v_env->>'uid';
    v_payload    := v_env->'payload';
    v_parked_seq := nullif(v_env->>'parked_seq', '')::bigint;

    if v_table is null or v_uid is null
       or jsonb_typeof(v_payload) <> 'object' then
      return jsonb_build_object('ok', false, 'error', jsonb_build_object(
        'code', 'malformed_envelope', 'message',
        'Every envelope needs table, uid and a payload object'));
    end if;

    if v_table not in (
      'events', 'products', 'accounts', 'budget_plans', 'collections_targets',
      'deliveries', 'attendance_records', 'delivery_status_history',
      'daily_close_actions', 'physical_cash_counts', 'settings', 'store_profile'
    ) then
      return jsonb_build_object('ok', false, 'error', jsonb_build_object(
        'code', 'unknown_table', 'message', 'Unknown synced table: ' || v_table));
    end if;

    -- D8 (unchanged): corrections of recorded history from privileged sources only
    if v_table = 'events'
       and (v_payload->>'corrects_event_uid') is not null
       and v_staff.role not in ('owner', 'admin') then
      return jsonb_build_object('ok', false, 'error', jsonb_build_object(
        'code', 'correction_privilege_required', 'message',
        'Correcting recorded history requires an owner or admin account'));
    end if;

    -- erratum 2: qualify columns (unqualified shop_id collides with the param, 42702)
    select * into v_existing from public.sync_records
     where public.sync_records.shop_id    = v_shop
       and public.sync_records.table_name = v_table
       and public.sync_records.row_uid    = v_uid;

    if found then
      -- INVARIANT 4: append-only tables are insert-only
      if v_table in ('events', 'delivery_status_history',
                     'daily_close_actions', 'physical_cash_counts') then
        if public.sync_normalize_payload(v_existing.payload)
           is distinct from public.sync_normalize_payload(v_payload) then
          insert into public.audit_log (action, business_id, performed_by,
                                        performed_by_username, detail)
          values ('sync_append_only_refused', v_staff.business_id, v_staff.id,
                  v_staff.username,
                  jsonb_build_object('table', v_table, 'uid', v_uid,
                                     'shop', v_shop, 'device', device_id));
        end if;
        continue;  -- insert-only: never update; NOT counted in 'applied' (erratum 4)
      end if;

      -- master-data role gate
      if v_table in ('products', 'accounts', 'settings', 'store_profile')
         and v_staff.role not in ('owner', 'admin') then
        return jsonb_build_object('ok', false, 'error', jsonb_build_object(
          'code', 'master_data_privilege_required', 'message',
          'Updating ' || v_table || ' requires an owner or admin account'));
      end if;

      -- INVARIANT 7: true-conflict audit, losing payload preserved
      if public.sync_normalize_payload(v_existing.payload)
         is distinct from public.sync_normalize_payload(v_payload)
         and v_existing.origin_device is distinct from device_id
         and (
              (pull_cursor is not null and v_existing.server_seq > pull_cursor)
              or (v_parked_seq is not null
                  and v_existing.server_seq >= v_parked_seq)
             ) then
        insert into public.audit_log (action, business_id, performed_by,
                                      performed_by_username, detail)
        values ('sync_conflict', v_staff.business_id, v_staff.id,
                v_staff.username,
                jsonb_build_object(
                  'table', v_table, 'uid', v_uid, 'shop', v_shop,
                  'loser_payload', v_existing.payload,
                  'loser_device',  v_existing.origin_device,
                  'loser_seq',     v_existing.server_seq,
                  'winner_device', device_id,
                  'detected_by',   case when v_parked_seq is not null
                                        then 'parked_seq' else 'pull_cursor' end));
        v_conflicts := v_conflicts + 1;
      end if;
    end if;

    -- INVARIANT 8: unchanged re-push is a complete no-op (WHERE fails -> nothing set)
    -- erratum 3: constraint-name target (inference cols collide with the param)
    insert into public.sync_records
      (business_id, shop_id, table_name, row_uid, payload, origin_device)
    values (
      (select business_id from public.shops where id = v_shop),
      v_shop, v_table, v_uid, v_payload, device_id)
    on conflict on constraint sync_records_shop_table_uid do update
      set payload       = excluded.payload,
          origin_device = excluded.origin_device,
          received_at   = now()
      where public.sync_normalize_payload(public.sync_records.payload)
            is distinct from public.sync_normalize_payload(excluded.payload);

    v_applied := v_applied + 1;
  end loop;

  insert into public.audit_log (action, business_id, performed_by,
                                performed_by_username, detail)
  values ('sync_push', v_staff.business_id, v_staff.id, v_staff.username,
          jsonb_build_object('envelopes', v_applied, 'conflicts', v_conflicts,
                             'device', device_id, 'shop', v_shop));

  return jsonb_build_object('ok', true, 'applied', v_applied,
                            'conflicts', v_conflicts,
                            'server_time_epoch_ms',
                            (extract(epoch from now()) * 1000)::bigint);
end
